from __future__ import annotations
import argparse
from .common import record, run_purpose

PURPOSE = 'design'
CATALOG = [{'id': 'design-bounded-subscriber-bus', 'concept': 'bounded-subscriber-event-bus', 'domain': 'software-engineering', 'subdomain': 'event-processing', 'difficulty': 'advanced', 'task_type': 'design', 'verification_method': 'rubric', 'question': 'Design an in-process event bus where one slow subscriber must not cause unbounded memory growth or stall every unrelated subscriber.', 'answer': 'Give each subscriber an explicit delivery policy and bounded queue/concurrency budget rather than one unbounded global queue.\n\nA slow subscriber can be isolated with its own queue and worker. When its bound is reached, apply a defined policy such as backpressure to the producer, drop/coalesce events that are safe to lose, or disconnect/fail that subscriber. The policy must reflect event semantics.\n\nExpose queue depth, lag, drops, and processing latency. If events require durable guaranteed delivery, an in-process best-effort bus may be the wrong abstraction and durable messaging should be considered.', 'verification_details': 'Must isolate subscriber capacity, bound queues, define overflow semantics, expose lag/drop metrics, and distinguish best-effort in-process delivery from durable messaging.', 'tags': ['event-bus', 'backpressure', 'queue', 'isolation']}, {'id': 'design-zero-copy-ownership', 'concept': 'zero-copy-buffer-ownership-api', 'domain': 'systems-programming', 'subdomain': 'memory-ownership', 'difficulty': 'expert', 'task_type': 'architecture-analysis', 'verification_method': 'rubric', 'question': 'Design a zero-copy buffer API shared across asynchronous producer and consumer components. The main risk is use-after-free when ownership crosses callback boundaries.', 'answer': 'Make ownership explicit in the type/API contract. A buffer should have one clear owner, transferable ownership, or a reference-counted lifetime; borrowed views must not outlive the backing object.\n\nAsynchronous submission should either consume/move the buffer, retain a reference until completion, or require the caller to keep it alive under a documented completion contract. Completion returns/releases ownership exactly once.\n\nSeparate mutable and immutable access where possible so two components do not concurrently modify the same bytes. Avoid raw pointer conventions whose lifetime exists only in comments.', 'verification_details': 'Must define explicit ownership/lifetime across async boundaries, ensure completion releases or returns ownership exactly once, and prevent borrowed views from outliving backing storage.', 'tags': ['zero-copy', 'ownership', 'async', 'lifetime']}, {'id': 'design-work-stealing-pool', 'concept': 'work-stealing-scheduler-design', 'domain': 'operating-systems', 'subdomain': 'scheduling', 'difficulty': 'advanced', 'task_type': 'design', 'verification_method': 'rubric', 'question': 'Design a CPU task scheduler for many small independent jobs where a single global queue has become a contention point on a many-core machine.', 'answer': "Use per-worker deques. A worker normally pushes/pops its own tasks locally, while an idle worker steals work from another worker, typically from the opposite end of that worker's deque.\n\nThis reduces traffic on one global queue and improves locality for tasks spawned by a worker. Use randomized or topology-aware victim selection to avoid all idle workers attacking the same victim.\n\nDefine behavior for task affinity, blocking tasks, shutdown, and fairness; work stealing is not automatically appropriate for tasks that must stay on a specific CPU or frequently block on external I/O.", 'verification_details': 'Must use mostly-local worker queues with stealing for load balance, address contention/locality, and state limits for affinity/blocking/fairness.', 'tags': ['scheduler', 'work-stealing', 'multicore', 'deque']}, {'id': 'design-hierarchical-counters', 'concept': 'hierarchical-per-core-counters', 'domain': 'computer-architecture', 'subdomain': 'contention', 'difficulty': 'advanced', 'task_type': 'architecture-analysis', 'verification_method': 'rubric', 'question': 'A global atomic request counter is updated millions of times per second by all cores and has become a cache-coherence hotspot. Design a lower-contention counting scheme.', 'answer': 'Keep independent counters per CPU, worker, or shard so the hot update path touches mostly local cache lines. Pad/alignment may be needed to keep unrelated counters from sharing a line.\n\nReaders that need a global total aggregate the shards periodically or on demand. If an exactly current linearizable total is required on every read, the design must pay additional synchronization cost; many telemetry counters can accept a slightly stale aggregate.\n\nHandle worker creation/removal and counter overflow explicitly. The design trades cheap distributed updates for more expensive aggregation.', 'verification_details': 'Must shard hot updates, avoid cache-line sharing between shards, explain aggregation/staleness tradeoffs, and state the stronger cost of exact linearizable totals.', 'tags': ['atomic', 'cache-coherence', 'sharding', 'counter']}, {'id': 'design-config-rollout', 'concept': 'validated-config-rollout-rollback', 'domain': 'linux-infrastructure', 'subdomain': 'operations', 'difficulty': 'intermediate', 'task_type': 'design', 'verification_method': 'rubric', 'question': 'Design a configuration rollout process for hundreds of Linux services so a bad configuration is detected before it reaches every host and rollback is straightforward.', 'answer': 'Treat configuration as a versioned artifact. Validate syntax and semantic constraints before deployment, then roll it out to a small canary subset first.\n\nServices should expose which configuration version is active and fail a reload safely without destroying the previously working state. Promote gradually while watching health/SLO signals, and stop automatically when defined failure thresholds are crossed.\n\nKeep the previous known-good version readily available so rollback is a version change rather than an ad-hoc edit. Record deployment and validation results for auditability.', 'verification_details': 'Must use versioned validated artifacts, canary/staged rollout, observable active versions, safe reload behavior, automatic stop criteria, and known-good rollback.', 'tags': ['configuration', 'rollout', 'canary', 'rollback']}, {'id': 'design-rss-affinity', 'concept': 'nic-rss-cpu-affinity-design', 'domain': 'networking', 'subdomain': 'packet-processing', 'difficulty': 'advanced', 'task_type': 'architecture-analysis', 'verification_method': 'rubric', 'question': 'Design CPU and queue placement for a high-throughput multi-queue NIC so receive processing does not bounce packets and cache state unnecessarily across cores.', 'answer': "Use RSS to spread flows across hardware receive queues with a stable hash. Map queue interrupts/polling to CPUs deliberately and keep the application worker that handles a flow close to the CPU/NUMA node receiving that queue when practical.\n\nAlign memory allocation and NIC locality with the socket/NUMA node, and avoid configurations where irqbalance or manual affinity repeatedly moves a hot queue between distant CPUs.\n\nMeasure per-queue load because a poor RSS hash or a few elephant flows can still create imbalance. The goal is not simply 'one queue per core' but coherent queue/CPU/worker placement with observed load balance.", 'verification_details': 'Must coordinate RSS queues, interrupt/polling affinity, worker and NUMA placement, measure per-queue imbalance, and avoid simplistic queue-count-only reasoning.', 'tags': ['rss', 'nic', 'affinity', 'numa']}, {'id': 'design-saga-compensation', 'concept': 'saga-compensation-workflow', 'domain': 'distributed-systems', 'subdomain': 'transactions', 'difficulty': 'expert', 'task_type': 'architecture-analysis', 'verification_method': 'rubric', 'question': 'A workflow reserves inventory, charges payment, and creates shipping across three services that cannot share one database transaction. Design failure handling without pretending the whole workflow is atomic.', 'answer': 'Model the workflow as a saga with durable step state. Each successful forward step has an explicitly defined compensating action where business semantics permit it, such as releasing reserved inventory or issuing a refund.\n\nPersist progress before/around external actions using idempotency keys so retries after crashes do not duplicate effects. Compensation is itself fallible and must be retryable and observable.\n\nNot every action is perfectly reversible; the design must define terminal manual-review states for cases where compensation cannot restore the original world. A saga provides coordinated recovery, not ACID atomicity across services.', 'verification_details': 'Must persist saga progress, define idempotent forward/compensating actions, make compensation retryable/observable, and state that compensation is not equivalent to distributed ACID rollback.', 'tags': ['saga', 'compensation', 'distributed-transaction', 'idempotency']}, {'id': 'design-merkle-anti-entropy', 'concept': 'merkle-tree-anti-entropy', 'domain': 'distributed-systems', 'subdomain': 'replication', 'difficulty': 'advanced', 'task_type': 'design', 'verification_method': 'rubric', 'question': 'Design an anti-entropy mechanism for replicas that contain millions of key/value entries. Sending the entire dataset to compare replicas is too expensive.', 'answer': "Partition the keyspace deterministically and maintain a Merkle tree or similar hierarchical digest over each partition. Replicas first compare root digests; when roots differ, descend only into subtrees whose hashes differ until the mismatching ranges are localized.\n\nExchange actual keys/versions only for those ranges, then reconcile according to the datastore's version/conflict rules.\n\nHash construction must use deterministic ordering/encoding, and trees must represent comparable membership/version snapshots. Anti-entropy repairs divergence in the background; it does not by itself define the consistency semantics of foreground reads and writes.", 'verification_details': 'Must compare hierarchical digests, descend only into mismatching ranges, use deterministic representation, reconcile concrete records at leaves, and separate repair from consistency semantics.', 'tags': ['merkle-tree', 'anti-entropy', 'replication', 'repair']}, {'id': 'design-checkpoint-storage', 'concept': 'tiered-training-checkpoint-storage', 'domain': 'compute-model-infrastructure', 'subdomain': 'checkpointing', 'difficulty': 'intermediate', 'task_type': 'design', 'verification_method': 'rubric', 'question': 'Design checkpoint storage for long-running model training where local NVMe is fast but node-local data disappears if the machine fails. Object storage is durable but slower.', 'answer': 'Use local NVMe as a staging tier and durable object storage as the authoritative recovery tier.\n\nWrite a checkpoint into a temporary/versioned local location, finalize it atomically, then upload it asynchronously with a manifest containing step, files, sizes, and hashes. Mark a checkpoint durable only after all required objects and the manifest are committed.\n\nRetain a small number of recent local checkpoints for fast restart while periodically pruning according to policy. Resume logic should choose the newest complete verified durable checkpoint, not simply the newest filename.', 'verification_details': 'Must separate fast local staging from durable storage, use completeness/hash manifests, define when a checkpoint becomes durable, and resume only from complete verified checkpoints.', 'tags': ['training', 'checkpoint', 'object-storage', 'durability']}, {'id': 'design-graceful-degradation', 'concept': 'overload-graceful-degradation-tiers', 'domain': 'engineering-reasoning', 'subdomain': 'resilience', 'difficulty': 'advanced', 'task_type': 'technical-decision', 'verification_method': 'rubric', 'question': 'Design overload behavior for a service that has essential requests plus optional enrichment work. The current system tries to do everything until queues explode.', 'answer': 'Classify work by business importance and cost. Protect the essential path with reserved capacity and deadlines, then shed or disable optional enrichment before essential requests saturate.\n\nUse explicit admission control rather than letting queues grow without bound. Trigger degradation from measured load/latency/queue signals with hysteresis so the service does not flap between modes.\n\nExpose the active degradation level and dropped optional work. Recovery should restore optional features gradually after headroom returns. The objective is controlled loss of nonessential quality instead of uncontrolled failure of the whole service.', 'verification_details': 'Must prioritize essential work, bound/admit load, shed optional work before saturation, use observable thresholds/hysteresis, and define controlled recovery.', 'tags': ['overload', 'load-shedding', 'graceful-degradation', 'capacity']}]

FAMILIES = [
    {
        "id": x["id"],
        "concept": x["concept"],
        "domain": x["domain"],
    }
    for x in CATALOG
]

BY_ID = {x["id"]: x for x in CATALOG}

def build(family, rng, rid, _difficulty):
    x = BY_ID[family["id"]]
    return record(
        rid,
        x["domain"],
        x["subdomain"],
        x["task_type"],
        x["difficulty"],
        x["question"],
        x["answer"],
        x["verification_method"],
        x["verification_details"],
        x["tags"],
    )

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--records", type=int, default=len(FAMILIES))
    ap.add_argument("--seed", type=int, default=20260914)
    args = ap.parse_args()
    run_purpose(
        purpose=PURPOSE,
        families=FAMILIES,
        build=build,
        records_requested=args.records,
        seed=args.seed,
    )

if __name__ == "__main__":
    main()
